from PIL import Image,ImageOps
from produce import EP,ROOT,request,save
OUT=EP/'image/character-current';OUT.mkdir(parents=True,exist_ok=True)
ref=EP/'image/references/worker-reference-style.png'
can=Image.new('RGB',(2400,1200),(114,120,122))
a=Image.open(ROOT/'projects/人生体验/planning/refs/主角-多角度.jpg').crop((1200,0,1800,600));a=ImageOps.contain(a,(800,1200));can.paste(a,((800-a.width)//2,(1200-a.height)//2))
b=ImageOps.fit(Image.open(EP/'image/backgrounds/kitchen-full.png'),(1600,1200));can.paste(b,(800,0));can.save(ref)
prompt='''Create ONE new full-body protagonist character illustration for a cleaning-work story. Reference LEFT is cartoon SHAPE LANGUAGE and painted shading only; reference RIGHT is the current apartment environment and daylight only. Output ONE unified 16:9 landscape scene, NO reference panels. Interpret left figure's round blank-faced adult design faithfully: bald pale grey-white large round head, small simple C-shaped ears, NO nose, NO hair, NO realistic facial anatomy, small black oval eyes with understated tiny highlights, two thin expressive curved eyebrows, small simple mouth, relaxed concentrated expression. IMPORTANT about 3.2-3.5 HEADS TALL overall, compact clothed body, narrow shoulders, full volumetric sleeves and trouser legs, small solid gloved hands and small practical shoes. NOT 5-7 heads tall, NOT black rod stick arms or legs, NOT chibi baby or cute mascot, NOT realistic man, NOT anime hair, NOT anime large glossy eyes. Deep grey-brown clean hand-drawn contours with subtle natural variation, painted flat shapes with one restrained cool-grey soft shadow plane; pale head receives soft window light and grey-green reflected light, not pure glowing white. Reference shows a survival character; DO NOT copy its green coat, backpack, ripped clothes or wasteland. Design a new experienced cleaner: faded muted blue-grey zip-front work jacket with just two practical pockets, dark charcoal work trousers, mustard-yellow rubber cleaning gloves, dark work shoes, a few cloth folds and localized work scuffs. No hood, no backpack, no props. Hands visibly relaxed at sides, three-quarter full-body standing pose with feet naturally planted. Mature and quietly observant, not smiling at camera. Place in same old painted kitchen with sea-green tiles, grime and natural right-back window daylight. Character clearly occupies floor with grounded contact shadows and lighting shared with environment. Keep entire head and shoes inside frame with ample margin, character about 75 percent frame height. High-detail hand-painted background with readable materials and spatial depth, character simplified but fully clothed with volume; environment retains established kitchen geometry. No text, letters, logos, watermark, UI, comic surprise marks, panels, extra people or cats. Reference pixels must not appear as pasted elements: draw a fresh cleaner and new framing.'''
src=request('worker-reference-roundhead',prompt,0,ref,dict(stage='reference-style-character',character_id='worker',user_approved_reference='末日独存 https://v.douyin.com/HCQPssu6cGI/',reference_roles={str(ROOT/'projects/人生体验/planning/refs/主角-多角度.jpg'):'圆头/五官/完整着装身体/手绘明暗，仅画法',str(EP/'image/backgrounds/kitchen-full.png'):'本集厨房及光线'},cast='worker',fact='蓝灰工作服、黄色手套的圆头手绘清洁工，全身形象'))
out=OUT/'清理垃圾屋_主角_圆头手绘_v1.png'
with Image.open(src) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(out)
save(EP/'qa/character-current.json',dict(file=str(out.relative_to(EP)),style='参考片圆头手绘人物',status='待目检'))
print('READY',flush=True)
